# ! [doc = " Unix-specific extensions to primitives in the [`std::fs`] module."] # ! [doc = ""] # ! [doc = " [`std::fs`]: crate::fs"] # ! [stable (feature = "rust1" , since = "1.0.0")] use split_decls_genesis :: ourprelude :: * ; #[allow (unused_imports)] use io :: { Read , Write } ; use super :: platform :: fs :: MetadataExt as _ ; use crate :: ffi :: OsStr ; use crate :: fs :: { self , OpenOptions , Permissions } ; use crate :: io :: BorrowedCursor ; use crate :: os :: unix :: io :: { AsFd , AsRawFd } ; use crate :: path :: Path ; use crate :: sealed :: Sealed ; use crate :: sys_common :: { AsInner , AsInnerMut , FromInner } ; use crate :: { io , sys } ; #[cfg (test)] mod tests ; #[doc = " Unix-specific extensions to [`fs::File`]."] #[stable (feature = "file_offset" , since = "1.15.0")] pub trait FileExt { #[doc = " Reads a number of bytes starting from a given offset."] #[doc = ""] #[doc = " Returns the number of bytes read."] #[doc = ""] #[doc = " The offset is relative to the start of the file and thus independent"] #[doc = " from the current cursor."] #[doc = ""] #[doc = " The current file cursor is not affected by this function."] #[doc = ""] #[doc = " Note that similar to [`File::read`], it is not an error to return with a"] #[doc = " short read."] #[doc = ""] #[doc = " [`File::read`]: fs::File::read"] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::io;"] #[doc = " use std::fs::File;"] #[doc = " use std::os::unix::prelude::FileExt;"] #[doc = ""] #[doc = " fn main() -> io::Result<()> {"] #[doc = "     let mut buf = [0u8; 8];"] #[doc = "     let file = File::open(\"foo.txt\")?;"] #[doc = ""] #[doc = "     // We now read 8 bytes from the offset 10."] #[doc = "     let num_bytes_read = file.read_at(&mut buf, 10)?;"] #[doc = "     println!(\"read {num_bytes_read} bytes: {buf:?}\");"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[stable (feature = "file_offset" , since = "1.15.0")] fn read_at (& self , buf : & mut [u8] , offset : u64) -> io :: Result < usize > ; #[doc = " Like `read_at`, except that it reads into a slice of buffers."] #[doc = ""] #[doc = " Data is copied to fill each buffer in order, with the final buffer"] #[doc = " written to possibly being only partially filled. This method must behave"] #[doc = " equivalently to a single call to read with concatenated buffers."] #[unstable (feature = "unix_file_vectored_at" , issue = "89517")] fn read_vectored_at (& self , bufs : & mut [io :: IoSliceMut < '_ >] , offset : u64) -> io :: Result < usize > { io :: default_read_vectored (| b | self . read_at (b , offset) , bufs) } #[doc = " Reads the exact number of bytes required to fill `buf` from the given offset."] #[doc = ""] #[doc = " The offset is relative to the start of the file and thus independent"] #[doc = " from the current cursor."] #[doc = ""] #[doc = " The current file cursor is not affected by this function."] #[doc = ""] #[doc = " Similar to [`io::Read::read_exact`] but uses [`read_at`] instead of `read`."] #[doc = ""] #[doc = " [`read_at`]: FileExt::read_at"] #[doc = ""] #[doc = " # Errors"] #[doc = ""] #[doc = " If this function encounters an error of the kind"] #[doc = " [`io::ErrorKind::Interrupted`] then the error is ignored and the operation"] #[doc = " will continue."] #[doc = ""] #[doc = " If this function encounters an \"end of file\" before completely filling"] #[doc = " the buffer, it returns an error of the kind [`io::ErrorKind::UnexpectedEof`]."] #[doc = " The contents of `buf` are unspecified in this case."] #[doc = ""] #[doc = " If any other read error is encountered then this function immediately"] #[doc = " returns. The contents of `buf` are unspecified in this case."] #[doc = ""] #[doc = " If this function returns an error, it is unspecified how many bytes it"] #[doc = " has read, but it will never read more than would be necessary to"] #[doc = " completely fill the buffer."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::io;"] #[doc = " use std::fs::File;"] #[doc = " use std::os::unix::prelude::FileExt;"] #[doc = ""] #[doc = " fn main() -> io::Result<()> {"] #[doc = "     let mut buf = [0u8; 8];"] #[doc = "     let file = File::open(\"foo.txt\")?;"] #[doc = ""] #[doc = "     // We now read exactly 8 bytes from the offset 10."] #[doc = "     file.read_exact_at(&mut buf, 10)?;"] #[doc = "     println!(\"read {} bytes: {:?}\", buf.len(), buf);"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[stable (feature = "rw_exact_all_at" , since = "1.33.0")] fn read_exact_at (& self , mut buf : & mut [u8] , mut offset : u64) -> io :: Result < () > { while ! buf . is_empty () { match self . read_at (buf , offset) { Ok (0) => break , Ok (n) => { let tmp = buf ; buf = & mut tmp [n ..] ; offset += n as u64 ; } Err (ref e) if e . is_interrupted () => { } Err (e) => return Err (e) , } } if ! buf . is_empty () { Err (io :: Error :: READ_EXACT_EOF) } else { Ok (()) } } #[doc = " Reads some bytes starting from a given offset into the buffer."] #[doc = ""] #[doc = " This equivalent to the [`read_at`](FileExt::read_at) method, except that it is passed a"] #[doc = " [`BorrowedCursor`] rather than `&mut [u8]` to allow use with uninitialized buffers. The new"] #[doc = " data will be appended to any existing contents of `buf`."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " #![feature(core_io_borrowed_buf)]"] #[doc = " #![feature(read_buf_at)]"] #[doc = ""] #[doc = " use std::io;"] #[doc = " use std::io::BorrowedBuf;"] #[doc = " use std::fs::File;"] #[doc = " use std::mem::MaybeUninit;"] #[doc = " use std::os::unix::prelude::*;"] #[doc = ""] #[doc = " fn main() -> io::Result<()> {"] #[doc = "     let mut file = File::open(\"pi.txt\")?;"] #[doc = ""] #[doc = "     // Read some bytes starting from offset 2"] #[doc = "     let mut buf: [MaybeUninit<u8>; 10] = [MaybeUninit::uninit(); 10];"] #[doc = "     let mut buf = BorrowedBuf::from(buf.as_mut_slice());"] #[doc = "     file.read_buf_at(buf.unfilled(), 2)?;"] #[doc = ""] #[doc = "     assert!(buf.filled().starts_with(b\"1\"));"] #[doc = ""] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[unstable (feature = "read_buf_at" , issue = "140771")] fn read_buf_at (& self , buf : BorrowedCursor < '_ > , offset : u64) -> io :: Result < () > { io :: default_read_buf (| b | self . read_at (b , offset) , buf) } #[doc = " Reads the exact number of bytes required to fill the buffer from a given offset."] #[doc = ""] #[doc = " This is equivalent to the [`read_exact_at`](FileExt::read_exact_at) method, except that it"] #[doc = " is passed a [`BorrowedCursor`] rather than `&mut [u8]` to allow use with uninitialized"] #[doc = " buffers. The new data will be appended to any existing contents of `buf`."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " #![feature(core_io_borrowed_buf)]"] #[doc = " #![feature(read_buf_at)]"] #[doc = ""] #[doc = " use std::io;"] #[doc = " use std::io::BorrowedBuf;"] #[doc = " use std::fs::File;"] #[doc = " use std::mem::MaybeUninit;"] #[doc = " use std::os::unix::prelude::*;"] #[doc = ""] #[doc = " fn main() -> io::Result<()> {"] #[doc = "     let mut file = File::open(\"pi.txt\")?;"] #[doc = ""] #[doc = "     // Read exactly 10 bytes starting from offset 2"] #[doc = "     let mut buf: [MaybeUninit<u8>; 10] = [MaybeUninit::uninit(); 10];"] #[doc = "     let mut buf = BorrowedBuf::from(buf.as_mut_slice());"] #[doc = "     file.read_buf_exact_at(buf.unfilled(), 2)?;"] #[doc = ""] #[doc = "     assert_eq!(buf.filled(), b\"1415926535\");"] #[doc = ""] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[unstable (feature = "read_buf_at" , issue = "140771")] fn read_buf_exact_at (& self , mut buf : BorrowedCursor < '_ > , mut offset : u64) -> io :: Result < () > { while buf . capacity () > 0 { let prev_written = buf . written () ; match self . read_buf_at (buf . reborrow () , offset) { Ok (()) => { } Err (e) if e . is_interrupted () => { } Err (e) => return Err (e) , } let n = buf . written () - prev_written ; offset += n as u64 ; if n == 0 { return Err (io :: Error :: READ_EXACT_EOF) ; } } Ok (()) } #[doc = " Writes a number of bytes starting from a given offset."] #[doc = ""] #[doc = " Returns the number of bytes written."] #[doc = ""] #[doc = " The offset is relative to the start of the file and thus independent"] #[doc = " from the current cursor."] #[doc = ""] #[doc = " The current file cursor is not affected by this function."] #[doc = ""] #[doc = " When writing beyond the end of the file, the file is appropriately"] #[doc = " extended and the intermediate bytes are initialized with the value 0."] #[doc = ""] #[doc = " Note that similar to [`File::write`], it is not an error to return a"] #[doc = " short write."] #[doc = ""] #[doc = " # Bug"] #[doc = " On some systems, `write_at` utilises [`pwrite64`] to write to files."] #[doc = " However, this syscall has a [bug] where files opened with the `O_APPEND`"] #[doc = " flag fail to respect the offset parameter, always appending to the end"] #[doc = " of the file instead."] #[doc = ""] #[doc = " It is possible to inadvertently set this flag, like in the example below."] #[doc = " Therefore, it is important to be vigilant while changing options to mitigate"] #[doc = " unexpected behavior."] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::fs::File;"] #[doc = " use std::io;"] #[doc = " use std::os::unix::prelude::FileExt;"] #[doc = ""] #[doc = " fn main() -> io::Result<()> {"] #[doc = "     // Open a file with the append option (sets the `O_APPEND` flag)"] #[doc = "     let file = File::options().append(true).open(\"foo.txt\")?;"] #[doc = ""] #[doc = "     // We attempt to write at offset 10; instead appended to EOF"] #[doc = "     file.write_at(b\"sushi\", 10)?;"] #[doc = ""] #[doc = "     // foo.txt is 5 bytes long instead of 15"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " [`File::write`]: fs::File::write"] #[doc = " [`pwrite64`]: https://man7.org/linux/man-pages/man2/pwrite.2.html"] #[doc = " [bug]: https://man7.org/linux/man-pages/man2/pwrite.2.html#BUGS"] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::fs::File;"] #[doc = " use std::io;"] #[doc = " use std::os::unix::prelude::FileExt;"] #[doc = ""] #[doc = " fn main() -> io::Result<()> {"] #[doc = "     let file = File::create(\"foo.txt\")?;"] #[doc = ""] #[doc = "     // We now write at the offset 10."] #[doc = "     file.write_at(b\"sushi\", 10)?;"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[stable (feature = "file_offset" , since = "1.15.0")] fn write_at (& self , buf : & [u8] , offset : u64) -> io :: Result < usize > ; #[doc = " Like `write_at`, except that it writes from a slice of buffers."] #[doc = ""] #[doc = " Data is copied from each buffer in order, with the final buffer read"] #[doc = " from possibly being only partially consumed. This method must behave as"] #[doc = " a call to `write_at` with the buffers concatenated would."] #[unstable (feature = "unix_file_vectored_at" , issue = "89517")] fn write_vectored_at (& self , bufs : & [io :: IoSlice < '_ >] , offset : u64) -> io :: Result < usize > { io :: default_write_vectored (| b | self . write_at (b , offset) , bufs) } #[doc = " Attempts to write an entire buffer starting from a given offset."] #[doc = ""] #[doc = " The offset is relative to the start of the file and thus independent"] #[doc = " from the current cursor."] #[doc = ""] #[doc = " The current file cursor is not affected by this function."] #[doc = ""] #[doc = " This method will continuously call [`write_at`] until there is no more data"] #[doc = " to be written or an error of non-[`io::ErrorKind::Interrupted`] kind is"] #[doc = " returned. This method will not return until the entire buffer has been"] #[doc = " successfully written or such an error occurs. The first error that is"] #[doc = " not of [`io::ErrorKind::Interrupted`] kind generated from this method will be"] #[doc = " returned."] #[doc = ""] #[doc = " # Errors"] #[doc = ""] #[doc = " This function will return the first error of"] #[doc = " non-[`io::ErrorKind::Interrupted`] kind that [`write_at`] returns."] #[doc = ""] #[doc = " [`write_at`]: FileExt::write_at"] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::fs::File;"] #[doc = " use std::io;"] #[doc = " use std::os::unix::prelude::FileExt;"] #[doc = ""] #[doc = " fn main() -> io::Result<()> {"] #[doc = "     let file = File::open(\"foo.txt\")?;"] #[doc = ""] #[doc = "     // We now write at the offset 10."] #[doc = "     file.write_all_at(b\"sushi\", 10)?;"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[stable (feature = "rw_exact_all_at" , since = "1.33.0")] fn write_all_at (& self , mut buf : & [u8] , mut offset : u64) -> io :: Result < () > { while ! buf . is_empty () { match self . write_at (buf , offset) { Ok (0) => { return Err (io :: Error :: WRITE_ALL_EOF) ; } Ok (n) => { buf = & buf [n ..] ; offset += n as u64 } Err (ref e) if e . is_interrupted () => { } Err (e) => return Err (e) , } } Ok (()) } } #[stable (feature = "file_offset" , since = "1.15.0")] impl FileExt for fs :: File { fn read_at (& self , buf : & mut [u8] , offset : u64) -> io :: Result < usize > { self . as_inner () . read_at (buf , offset) } fn read_buf_at (& self , buf : BorrowedCursor < '_ > , offset : u64) -> io :: Result < () > { self . as_inner () . read_buf_at (buf , offset) } fn read_vectored_at (& self , bufs : & mut [io :: IoSliceMut < '_ >] , offset : u64) -> io :: Result < usize > { self . as_inner () . read_vectored_at (bufs , offset) } fn write_at (& self , buf : & [u8] , offset : u64) -> io :: Result < usize > { self . as_inner () . write_at (buf , offset) } fn write_vectored_at (& self , bufs : & [io :: IoSlice < '_ >] , offset : u64) -> io :: Result < usize > { self . as_inner () . write_vectored_at (bufs , offset) } } #[doc = " Unix-specific extensions to [`fs::Permissions`]."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::fs::{File, Permissions};"] #[doc = " use std::io::{ErrorKind, Result as IoResult};"] #[doc = " use std::os::unix::fs::PermissionsExt;"] #[doc = ""] #[doc = " fn main() -> IoResult<()> {"] #[doc = "     let name = \"test_file_for_permissions\";"] #[doc = ""] #[doc = "     // make sure file does not exist"] #[doc = "     let _ = std::fs::remove_file(name);"] #[doc = "     assert_eq!("] #[doc = "         File::open(name).unwrap_err().kind(),"] #[doc = "         ErrorKind::NotFound,"] #[doc = "         \"file already exists\""] #[doc = "     );"] #[doc = ""] #[doc = "     // full read/write/execute mode bits for owner of file"] #[doc = "     // that we want to add to existing mode bits"] #[doc = "     let my_mode = 0o700;"] #[doc = ""] #[doc = "     // create new file with specified permissions"] #[doc = "     {"] #[doc = "         let file = File::create(name)?;"] #[doc = "         let mut permissions = file.metadata()?.permissions();"] #[doc = "         eprintln!(\"Current permissions: {:o}\", permissions.mode());"] #[doc = ""] #[doc = "         // make sure new permissions are not already set"] #[doc = "         assert!("] #[doc = "             permissions.mode() & my_mode != my_mode,"] #[doc = "             \"permissions already set\""] #[doc = "         );"] #[doc = ""] #[doc = "         // either use `set_mode` to change an existing Permissions struct"] #[doc = "         permissions.set_mode(permissions.mode() | my_mode);"] #[doc = ""] #[doc = "         // or use `from_mode` to construct a new Permissions struct"] #[doc = "         permissions = Permissions::from_mode(permissions.mode() | my_mode);"] #[doc = ""] #[doc = "         // write new permissions to file"] #[doc = "         file.set_permissions(permissions)?;"] #[doc = "     }"] #[doc = ""] #[doc = "     let permissions = File::open(name)?.metadata()?.permissions();"] #[doc = "     eprintln!(\"New permissions: {:o}\", permissions.mode());"] #[doc = ""] #[doc = "     // assert new permissions were set"] #[doc = "     assert_eq!("] #[doc = "         permissions.mode() & my_mode,"] #[doc = "         my_mode,"] #[doc = "         \"new permissions not set\""] #[doc = "     );"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::fs::Permissions;"] #[doc = " use std::os::unix::fs::PermissionsExt;"] #[doc = ""] #[doc = " // read/write for owner and read for others"] #[doc = " let my_mode = 0o644;"] #[doc = " let mut permissions = Permissions::from_mode(my_mode);"] #[doc = " assert_eq!(permissions.mode(), my_mode);"] #[doc = ""] #[doc = " // read/write/execute for owner"] #[doc = " let other_mode = 0o700;"] #[doc = " permissions.set_mode(other_mode);"] #[doc = " assert_eq!(permissions.mode(), other_mode);"] #[doc = " ```"] #[stable (feature = "fs_ext" , since = "1.1.0")] pub trait PermissionsExt { #[doc = " Returns the mode permission bits"] #[stable (feature = "fs_ext" , since = "1.1.0")] fn mode (& self) -> u32 ; #[doc = " Sets the mode permission bits."] #[stable (feature = "fs_ext" , since = "1.1.0")] fn set_mode (& mut self , mode : u32) ; #[doc = " Creates a new instance from the given mode permission bits."] #[stable (feature = "fs_ext" , since = "1.1.0")] #[cfg_attr (not (test) , rustc_diagnostic_item = "permissions_from_mode")] fn from_mode (mode : u32) -> Self ; } #[stable (feature = "fs_ext" , since = "1.1.0")] impl PermissionsExt for Permissions { fn mode (& self) -> u32 { self . as_inner () . mode () } fn set_mode (& mut self , mode : u32) { * self = Permissions :: from_inner (FromInner :: from_inner (mode)) ; } fn from_mode (mode : u32) -> Permissions { Permissions :: from_inner (FromInner :: from_inner (mode)) } } #[doc = " Unix-specific extensions to [`fs::OpenOptions`]."] #[stable (feature = "fs_ext" , since = "1.1.0")] pub trait OpenOptionsExt { #[doc = " Sets the mode bits that a new file will be created with."] #[doc = ""] #[doc = " If a new file is created as part of an `OpenOptions::open` call then this"] #[doc = " specified `mode` will be used as the permission bits for the new file."] #[doc = " If no `mode` is set, the default of `0o666` will be used."] #[doc = " The operating system masks out bits with the system's `umask`, to produce"] #[doc = " the final permissions."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::fs::OpenOptions;"] #[doc = " use std::os::unix::fs::OpenOptionsExt;"] #[doc = ""] #[doc = " # fn main() {"] #[doc = " let mut options = OpenOptions::new();"] #[doc = " options.mode(0o644); // Give read/write for owner and read for others."] #[doc = " let file = options.open(\"foo.txt\");"] #[doc = " # }"] #[doc = " ```"] #[stable (feature = "fs_ext" , since = "1.1.0")] fn mode (& mut self , mode : u32) -> & mut Self ; #[doc = " Pass custom flags to the `flags` argument of `open`."] #[doc = ""] #[doc = " The bits that define the access mode are masked out with `O_ACCMODE`, to"] #[doc = " ensure they do not interfere with the access mode set by Rust's options."] #[doc = ""] #[doc = " Custom flags can only set flags, not remove flags set by Rust's options."] #[doc = " This function overwrites any previously-set custom flags."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " # mod libc { pub const O_NOFOLLOW: i32 = 0; }"] #[doc = " use std::fs::OpenOptions;"] #[doc = " use std::os::unix::fs::OpenOptionsExt;"] #[doc = ""] #[doc = " # fn main() {"] #[doc = " let mut options = OpenOptions::new();"] #[doc = " options.write(true);"] #[doc = " options.custom_flags(libc::O_NOFOLLOW);"] #[doc = " let file = options.open(\"foo.txt\");"] #[doc = " # }"] #[doc = " ```"] #[stable (feature = "open_options_ext" , since = "1.10.0")] fn custom_flags (& mut self , flags : i32) -> & mut Self ; } #[stable (feature = "fs_ext" , since = "1.1.0")] impl OpenOptionsExt for OpenOptions { fn mode (& mut self , mode : u32) -> & mut OpenOptions { self . as_inner_mut () . mode (mode) ; self } fn custom_flags (& mut self , flags : i32) -> & mut OpenOptions { self . as_inner_mut () . custom_flags (flags) ; self } } #[doc = " Unix-specific extensions to [`fs::Metadata`]."] #[stable (feature = "metadata_ext" , since = "1.1.0")] pub trait MetadataExt { #[doc = " Returns the ID of the device containing the file."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::io;"] #[doc = " use std::fs;"] #[doc = " use std::os::unix::fs::MetadataExt;"] #[doc = ""] #[doc = " fn main() -> io::Result<()> {"] #[doc = "     let meta = fs::metadata(\"some_file\")?;"] #[doc = "     let dev_id = meta.dev();"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[stable (feature = "metadata_ext" , since = "1.1.0")] fn dev (& self) -> u64 ; #[doc = " Returns the inode number."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::fs;"] #[doc = " use std::os::unix::fs::MetadataExt;"] #[doc = " use std::io;"] #[doc = ""] #[doc = " fn main() -> io::Result<()> {"] #[doc = "     let meta = fs::metadata(\"some_file\")?;"] #[doc = "     let inode = meta.ino();"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[stable (feature = "metadata_ext" , since = "1.1.0")] fn ino (& self) -> u64 ; #[doc = " Returns the rights applied to this file."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::fs;"] #[doc = " use std::os::unix::fs::MetadataExt;"] #[doc = " use std::io;"] #[doc = ""] #[doc = " fn main() -> io::Result<()> {"] #[doc = "     let meta = fs::metadata(\"some_file\")?;"] #[doc = "     let mode = meta.mode();"] #[doc = "     let user_has_write_access      = mode & 0o200;"] #[doc = "     let user_has_read_write_access = mode & 0o600;"] #[doc = "     let group_has_read_access      = mode & 0o040;"] #[doc = "     let others_have_exec_access    = mode & 0o001;"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[stable (feature = "metadata_ext" , since = "1.1.0")] fn mode (& self) -> u32 ; #[doc = " Returns the number of hard links pointing to this file."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::fs;"] #[doc = " use std::os::unix::fs::MetadataExt;"] #[doc = " use std::io;"] #[doc = ""] #[doc = " fn main() -> io::Result<()> {"] #[doc = "     let meta = fs::metadata(\"some_file\")?;"] #[doc = "     let nb_hard_links = meta.nlink();"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[stable (feature = "metadata_ext" , since = "1.1.0")] fn nlink (& self) -> u64 ; #[doc = " Returns the user ID of the owner of this file."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::fs;"] #[doc = " use std::os::unix::fs::MetadataExt;"] #[doc = " use std::io;"] #[doc = ""] #[doc = " fn main() -> io::Result<()> {"] #[doc = "     let meta = fs::metadata(\"some_file\")?;"] #[doc = "     let user_id = meta.uid();"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[stable (feature = "metadata_ext" , since = "1.1.0")] fn uid (& self) -> u32 ; #[doc = " Returns the group ID of the owner of this file."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::fs;"] #[doc = " use std::os::unix::fs::MetadataExt;"] #[doc = " use std::io;"] #[doc = ""] #[doc = " fn main() -> io::Result<()> {"] #[doc = "     let meta = fs::metadata(\"some_file\")?;"] #[doc = "     let group_id = meta.gid();"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[stable (feature = "metadata_ext" , since = "1.1.0")] fn gid (& self) -> u32 ; #[doc = " Returns the device ID of this file (if it is a special one)."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::fs;"] #[doc = " use std::os::unix::fs::MetadataExt;"] #[doc = " use std::io;"] #[doc = ""] #[doc = " fn main() -> io::Result<()> {"] #[doc = "     let meta = fs::metadata(\"some_file\")?;"] #[doc = "     let device_id = meta.rdev();"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[stable (feature = "metadata_ext" , since = "1.1.0")] fn rdev (& self) -> u64 ; #[doc = " Returns the total size of this file in bytes."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::fs;"] #[doc = " use std::os::unix::fs::MetadataExt;"] #[doc = " use std::io;"] #[doc = ""] #[doc = " fn main() -> io::Result<()> {"] #[doc = "     let meta = fs::metadata(\"some_file\")?;"] #[doc = "     let file_size = meta.size();"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[stable (feature = "metadata_ext" , since = "1.1.0")] fn size (& self) -> u64 ; #[doc = " Returns the last access time of the file, in seconds since Unix Epoch."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::fs;"] #[doc = " use std::os::unix::fs::MetadataExt;"] #[doc = " use std::io;"] #[doc = ""] #[doc = " fn main() -> io::Result<()> {"] #[doc = "     let meta = fs::metadata(\"some_file\")?;"] #[doc = "     let last_access_time = meta.atime();"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[stable (feature = "metadata_ext" , since = "1.1.0")] fn atime (& self) -> i64 ; #[doc = " Returns the last access time of the file, in nanoseconds since [`atime`]."] #[doc = ""] #[doc = " [`atime`]: MetadataExt::atime"] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::fs;"] #[doc = " use std::os::unix::fs::MetadataExt;"] #[doc = " use std::io;"] #[doc = ""] #[doc = " fn main() -> io::Result<()> {"] #[doc = "     let meta = fs::metadata(\"some_file\")?;"] #[doc = "     let nano_last_access_time = meta.atime_nsec();"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[stable (feature = "metadata_ext" , since = "1.1.0")] fn atime_nsec (& self) -> i64 ; #[doc = " Returns the last modification time of the file, in seconds since Unix Epoch."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::fs;"] #[doc = " use std::os::unix::fs::MetadataExt;"] #[doc = " use std::io;"] #[doc = ""] #[doc = " fn main() -> io::Result<()> {"] #[doc = "     let meta = fs::metadata(\"some_file\")?;"] #[doc = "     let last_modification_time = meta.mtime();"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[stable (feature = "metadata_ext" , since = "1.1.0")] fn mtime (& self) -> i64 ; #[doc = " Returns the last modification time of the file, in nanoseconds since [`mtime`]."] #[doc = ""] #[doc = " [`mtime`]: MetadataExt::mtime"] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::fs;"] #[doc = " use std::os::unix::fs::MetadataExt;"] #[doc = " use std::io;"] #[doc = ""] #[doc = " fn main() -> io::Result<()> {"] #[doc = "     let meta = fs::metadata(\"some_file\")?;"] #[doc = "     let nano_last_modification_time = meta.mtime_nsec();"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[stable (feature = "metadata_ext" , since = "1.1.0")] fn mtime_nsec (& self) -> i64 ; #[doc = " Returns the last status change time of the file, in seconds since Unix Epoch."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::fs;"] #[doc = " use std::os::unix::fs::MetadataExt;"] #[doc = " use std::io;"] #[doc = ""] #[doc = " fn main() -> io::Result<()> {"] #[doc = "     let meta = fs::metadata(\"some_file\")?;"] #[doc = "     let last_status_change_time = meta.ctime();"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[stable (feature = "metadata_ext" , since = "1.1.0")] fn ctime (& self) -> i64 ; #[doc = " Returns the last status change time of the file, in nanoseconds since [`ctime`]."] #[doc = ""] #[doc = " [`ctime`]: MetadataExt::ctime"] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::fs;"] #[doc = " use std::os::unix::fs::MetadataExt;"] #[doc = " use std::io;"] #[doc = ""] #[doc = " fn main() -> io::Result<()> {"] #[doc = "     let meta = fs::metadata(\"some_file\")?;"] #[doc = "     let nano_last_status_change_time = meta.ctime_nsec();"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[stable (feature = "metadata_ext" , since = "1.1.0")] fn ctime_nsec (& self) -> i64 ; #[doc = " Returns the block size for filesystem I/O."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::fs;"] #[doc = " use std::os::unix::fs::MetadataExt;"] #[doc = " use std::io;"] #[doc = ""] #[doc = " fn main() -> io::Result<()> {"] #[doc = "     let meta = fs::metadata(\"some_file\")?;"] #[doc = "     let block_size = meta.blksize();"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[stable (feature = "metadata_ext" , since = "1.1.0")] fn blksize (& self) -> u64 ; #[doc = " Returns the number of blocks allocated to the file, in 512-byte units."] #[doc = ""] #[doc = " Please note that this may be smaller than `st_size / 512` when the file has holes."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::fs;"] #[doc = " use std::os::unix::fs::MetadataExt;"] #[doc = " use std::io;"] #[doc = ""] #[doc = " fn main() -> io::Result<()> {"] #[doc = "     let meta = fs::metadata(\"some_file\")?;"] #[doc = "     let blocks = meta.blocks();"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[stable (feature = "metadata_ext" , since = "1.1.0")] fn blocks (& self) -> u64 ; #[cfg (target_os = "vxworks")] #[stable (feature = "metadata_ext" , since = "1.1.0")] fn attrib (& self) -> u8 ; } #[stable (feature = "metadata_ext" , since = "1.1.0")] impl MetadataExt for fs :: Metadata { fn dev (& self) -> u64 { self . st_dev () } fn ino (& self) -> u64 { self . st_ino () } fn mode (& self) -> u32 { self . st_mode () } fn nlink (& self) -> u64 { self . st_nlink () } fn uid (& self) -> u32 { self . st_uid () } fn gid (& self) -> u32 { self . st_gid () } fn rdev (& self) -> u64 { self . st_rdev () } fn size (& self) -> u64 { self . st_size () } fn atime (& self) -> i64 { self . st_atime () } fn atime_nsec (& self) -> i64 { self . st_atime_nsec () } fn mtime (& self) -> i64 { self . st_mtime () } fn mtime_nsec (& self) -> i64 { self . st_mtime_nsec () } fn ctime (& self) -> i64 { self . st_ctime () } fn ctime_nsec (& self) -> i64 { self . st_ctime_nsec () } fn blksize (& self) -> u64 { self . st_blksize () } fn blocks (& self) -> u64 { self . st_blocks () } #[cfg (target_os = "vxworks")] fn attrib (& self) -> u8 { self . st_attrib () } } #[doc = " Unix-specific extensions for [`fs::FileType`]."] #[doc = ""] #[doc = " Adds support for special Unix file types such as block/character devices,"] #[doc = " pipes, and sockets."] #[stable (feature = "file_type_ext" , since = "1.5.0")] pub trait FileTypeExt { #[doc = " Returns `true` if this file type is a block device."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::fs;"] #[doc = " use std::os::unix::fs::FileTypeExt;"] #[doc = " use std::io;"] #[doc = ""] #[doc = " fn main() -> io::Result<()> {"] #[doc = "     let meta = fs::metadata(\"block_device_file\")?;"] #[doc = "     let file_type = meta.file_type();"] #[doc = "     assert!(file_type.is_block_device());"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[stable (feature = "file_type_ext" , since = "1.5.0")] fn is_block_device (& self) -> bool ; #[doc = " Returns `true` if this file type is a char device."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::fs;"] #[doc = " use std::os::unix::fs::FileTypeExt;"] #[doc = " use std::io;"] #[doc = ""] #[doc = " fn main() -> io::Result<()> {"] #[doc = "     let meta = fs::metadata(\"char_device_file\")?;"] #[doc = "     let file_type = meta.file_type();"] #[doc = "     assert!(file_type.is_char_device());"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[stable (feature = "file_type_ext" , since = "1.5.0")] fn is_char_device (& self) -> bool ; #[doc = " Returns `true` if this file type is a fifo."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::fs;"] #[doc = " use std::os::unix::fs::FileTypeExt;"] #[doc = " use std::io;"] #[doc = ""] #[doc = " fn main() -> io::Result<()> {"] #[doc = "     let meta = fs::metadata(\"fifo_file\")?;"] #[doc = "     let file_type = meta.file_type();"] #[doc = "     assert!(file_type.is_fifo());"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[stable (feature = "file_type_ext" , since = "1.5.0")] fn is_fifo (& self) -> bool ; #[doc = " Returns `true` if this file type is a socket."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::fs;"] #[doc = " use std::os::unix::fs::FileTypeExt;"] #[doc = " use std::io;"] #[doc = ""] #[doc = " fn main() -> io::Result<()> {"] #[doc = "     let meta = fs::metadata(\"unix.socket\")?;"] #[doc = "     let file_type = meta.file_type();"] #[doc = "     assert!(file_type.is_socket());"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[stable (feature = "file_type_ext" , since = "1.5.0")] fn is_socket (& self) -> bool ; } #[stable (feature = "file_type_ext" , since = "1.5.0")] impl FileTypeExt for fs :: FileType { fn is_block_device (& self) -> bool { self . as_inner () . is (libc :: S_IFBLK) } fn is_char_device (& self) -> bool { self . as_inner () . is (libc :: S_IFCHR) } fn is_fifo (& self) -> bool { self . as_inner () . is (libc :: S_IFIFO) } fn is_socket (& self) -> bool { self . as_inner () . is (libc :: S_IFSOCK) } } #[doc = " Unix-specific extension methods for [`fs::DirEntry`]."] #[stable (feature = "dir_entry_ext" , since = "1.1.0")] pub trait DirEntryExt { #[doc = " Returns the underlying `d_ino` field in the contained `dirent`"] #[doc = " structure."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```"] #[doc = " use std::fs;"] #[doc = " use std::os::unix::fs::DirEntryExt;"] #[doc = ""] #[doc = " if let Ok(entries) = fs::read_dir(\".\") {"] #[doc = "     for entry in entries {"] #[doc = "         if let Ok(entry) = entry {"] #[doc = "             // Here, `entry` is a `DirEntry`."] #[doc = "             println!(\"{:?}: {}\", entry.file_name(), entry.ino());"] #[doc = "         }"] #[doc = "     }"] #[doc = " }"] #[doc = " ```"] #[stable (feature = "dir_entry_ext" , since = "1.1.0")] fn ino (& self) -> u64 ; } #[stable (feature = "dir_entry_ext" , since = "1.1.0")] impl DirEntryExt for fs :: DirEntry { fn ino (& self) -> u64 { self . as_inner () . ino () } } #[doc = " Sealed Unix-specific extension methods for [`fs::DirEntry`]."] #[unstable (feature = "dir_entry_ext2" , issue = "85573")] pub trait DirEntryExt2 : Sealed { #[doc = " Returns a reference to the underlying `OsStr` of this entry's filename."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```"] #[doc = " #![feature(dir_entry_ext2)]"] #[doc = " use std::os::unix::fs::DirEntryExt2;"] #[doc = " use std::{fs, io};"] #[doc = ""] #[doc = " fn main() -> io::Result<()> {"] #[doc = "     let mut entries = fs::read_dir(\".\")?.collect::<Result<Vec<_>, io::Error>>()?;"] #[doc = "     entries.sort_unstable_by(|a, b| a.file_name_ref().cmp(b.file_name_ref()));"] #[doc = ""] #[doc = "     for p in entries {"] #[doc = "         println!(\"{p:?}\");"] #[doc = "     }"] #[doc = ""] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] fn file_name_ref (& self) -> & OsStr ; } #[doc = " Allows extension traits within `std`."] #[unstable (feature = "sealed" , issue = "none")] impl Sealed for fs :: DirEntry { } #[unstable (feature = "dir_entry_ext2" , issue = "85573")] impl DirEntryExt2 for fs :: DirEntry { fn file_name_ref (& self) -> & OsStr { self . as_inner () . file_name_os_str () } } #[doc = " Creates a new symbolic link on the filesystem."] #[doc = ""] #[doc = " The `link` path will be a symbolic link pointing to the `original` path."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::os::unix::fs;"] #[doc = ""] #[doc = " fn main() -> std::io::Result<()> {"] #[doc = "     fs::symlink(\"a.txt\", \"b.txt\")?;"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[stable (feature = "symlink" , since = "1.1.0")] pub fn symlink < P : AsRef < Path > , Q : AsRef < Path > > (original : P , link : Q) -> io :: Result < () > { sys :: fs :: symlink (original . as_ref () , link . as_ref ()) } #[doc = " Unix-specific extensions to [`fs::DirBuilder`]."] #[stable (feature = "dir_builder" , since = "1.6.0")] pub trait DirBuilderExt { #[doc = " Sets the mode to create new directories with. This option defaults to"] #[doc = " 0o777."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::fs::DirBuilder;"] #[doc = " use std::os::unix::fs::DirBuilderExt;"] #[doc = ""] #[doc = " let mut builder = DirBuilder::new();"] #[doc = " builder.mode(0o755);"] #[doc = " ```"] #[stable (feature = "dir_builder" , since = "1.6.0")] fn mode (& mut self , mode : u32) -> & mut Self ; } #[stable (feature = "dir_builder" , since = "1.6.0")] impl DirBuilderExt for fs :: DirBuilder { fn mode (& mut self , mode : u32) -> & mut fs :: DirBuilder { self . as_inner_mut () . set_mode (mode) ; self } } #[doc = " Change the owner and group of the specified path."] #[doc = ""] #[doc = " Specifying either the uid or gid as `None` will leave it unchanged."] #[doc = ""] #[doc = " Changing the owner typically requires privileges, such as root or a specific capability."] #[doc = " Changing the group typically requires either being the owner and a member of the group, or"] #[doc = " having privileges."] #[doc = ""] #[doc = " Be aware that changing owner clears the `suid` and `sgid` permission bits in most cases"] #[doc = " according to POSIX, usually even if the user is root. The sgid is not cleared when"] #[doc = " the file is non-group-executable. See: <https://www.man7.org/linux/man-pages/man2/chown.2.html>"] #[doc = " This call may also clear file capabilities, if there was any."] #[doc = ""] #[doc = " If called on a symbolic link, this will change the owner and group of the link target. To"] #[doc = " change the owner and group of the link itself, see [`lchown`]."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::os::unix::fs;"] #[doc = ""] #[doc = " fn main() -> std::io::Result<()> {"] #[doc = "     fs::chown(\"/sandbox\", Some(0), Some(0))?;"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[stable (feature = "unix_chown" , since = "1.73.0")] pub fn chown < P : AsRef < Path > > (dir : P , uid : Option < u32 > , gid : Option < u32 >) -> io :: Result < () > { sys :: fs :: chown (dir . as_ref () , uid . unwrap_or (u32 :: MAX) , gid . unwrap_or (u32 :: MAX)) } #[doc = " Change the owner and group of the file referenced by the specified open file descriptor."] #[doc = ""] #[doc = " For semantics and required privileges, see [`chown`]."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::os::unix::fs;"] #[doc = ""] #[doc = " fn main() -> std::io::Result<()> {"] #[doc = "     let f = std::fs::File::open(\"/file\")?;"] #[doc = "     fs::fchown(&f, Some(0), Some(0))?;"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[stable (feature = "unix_chown" , since = "1.73.0")] pub fn fchown < F : AsFd > (fd : F , uid : Option < u32 > , gid : Option < u32 >) -> io :: Result < () > { sys :: fs :: fchown (fd . as_fd () . as_raw_fd () , uid . unwrap_or (u32 :: MAX) , gid . unwrap_or (u32 :: MAX)) } #[doc = " Change the owner and group of the specified path, without dereferencing symbolic links."] #[doc = ""] #[doc = " Identical to [`chown`], except that if called on a symbolic link, this will change the owner"] #[doc = " and group of the link itself rather than the owner and group of the link target."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::os::unix::fs;"] #[doc = ""] #[doc = " fn main() -> std::io::Result<()> {"] #[doc = "     fs::lchown(\"/symlink\", Some(0), Some(0))?;"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[stable (feature = "unix_chown" , since = "1.73.0")] pub fn lchown < P : AsRef < Path > > (dir : P , uid : Option < u32 > , gid : Option < u32 >) -> io :: Result < () > { sys :: fs :: lchown (dir . as_ref () , uid . unwrap_or (u32 :: MAX) , gid . unwrap_or (u32 :: MAX)) } #[doc = " Change the root directory of the current process to the specified path."] #[doc = ""] #[doc = " This typically requires privileges, such as root or a specific capability."] #[doc = ""] #[doc = " This does not change the current working directory; you should call"] #[doc = " [`std::env::set_current_dir`][`crate::env::set_current_dir`] afterwards."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::os::unix::fs;"] #[doc = ""] #[doc = " fn main() -> std::io::Result<()> {"] #[doc = "     fs::chroot(\"/sandbox\")?;"] #[doc = "     std::env::set_current_dir(\"/\")?;"] #[doc = "     // continue working in sandbox"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[stable (feature = "unix_chroot" , since = "1.56.0")] #[cfg (not (target_os = "fuchsia"))] pub fn chroot < P : AsRef < Path > > (dir : P) -> io :: Result < () > { sys :: fs :: chroot (dir . as_ref ()) } #[doc = " Create a FIFO special file at the specified path with the specified mode."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " # #![feature(unix_mkfifo)]"] #[doc = " # #[cfg(not(unix))]"] #[doc = " # fn main() {}"] #[doc = " # #[cfg(unix)]"] #[doc = " # fn main() -> std::io::Result<()> {"] #[doc = " # use std::{"] #[doc = " #     os::unix::fs::{mkfifo, PermissionsExt},"] #[doc = " #     fs::{File, Permissions, remove_file},"] #[doc = " #     io::{Write, Read},"] #[doc = " # };"] #[doc = " # let _ = remove_file(\"/tmp/fifo\");"] #[doc = " mkfifo(\"/tmp/fifo\", Permissions::from_mode(0o774))?;"] #[doc = ""] #[doc = " let mut wx = File::options().read(true).write(true).open(\"/tmp/fifo\")?;"] #[doc = " let mut rx = File::open(\"/tmp/fifo\")?;"] #[doc = ""] #[doc = " wx.write_all(b\"hello, world!\")?;"] #[doc = " drop(wx);"] #[doc = ""] #[doc = " let mut s = String::new();"] #[doc = " rx.read_to_string(&mut s)?;"] #[doc = ""] #[doc = " assert_eq!(s, \"hello, world!\");"] #[doc = " # Ok(())"] #[doc = " # }"] #[doc = " ```"] #[unstable (feature = "unix_mkfifo" , issue = "139324")] pub fn mkfifo < P : AsRef < Path > > (path : P , permissions : Permissions) -> io :: Result < () > { sys :: fs :: mkfifo (path . as_ref () , permissions . mode ()) }